import { configure, fireEvent, render, screen } from '@testing-library/react';
import { MAX_LENGTHS_API } from '@proton/shared/lib/calendar/constants';
import SubscribeCalendarModal from './SubscribeCalendarModal';

jest.mock('../hooks/useGetCalendarSetup', () => ({
    __esModule: true,
    default: jest.fn(() => ({ error: false, loading: false })),
}));
jest.mock('../hooks/useGetCalendarActions', () => ({
    __esModule: true,
    default: jest.fn(() => ({ handleCreateCalendar: jest.fn() })),
}));

configure({ testIdAttribute: 'data-test-id' });

const setURL = (url: string) => {
    fireEvent.change(screen.getByTestId('input:calendar-subscription'), { target: { value: url } });
};

const getSubmit = () => screen.getByRole('button', { name: 'Add calendar', hidden: true });

describe('SubscribeCalendarModal', () => {
    beforeEach(() => render(<SubscribeCalendarModal isOpen />));

    it('only enables submission for a nonempty, valid URL within the API limit', () => {
        expect(getSubmit()).toBeDisabled();
        setURL('not a URL');
        expect(getSubmit()).toBeDisabled();
        setURL(`  https://example.com/${'a'.repeat(MAX_LENGTHS_API.CALENDAR_URL - 'https://example.com/'.length)}  `);
        expect(getSubmit()).toBeEnabled();
        setURL(`https://example.com/${'a'.repeat(MAX_LENGTHS_API.CALENDAR_URL)}`);
        expect(getSubmit()).toBeDisabled();
        expect(screen.getByText('URL is too long')).toBeInTheDocument();
    });

    it('shows extension, public link, and length warnings in priority order', () => {
        setURL(`https://calendar.google.com/public/${'a'.repeat(MAX_LENGTHS_API.CALENDAR_URL)}`);
        expect(screen.getByText('This link might be wrong')).toBeInTheDocument();
        expect(screen.queryByText('URL is too long')).not.toBeInTheDocument();
        setURL(`https://calendar.google.com/public/${'a'.repeat(MAX_LENGTHS_API.CALENDAR_URL)}.ics`);
        expect(
            screen.getByText('By using this link, Google will make the calendar you are subscribing to public')
        ).toBeInTheDocument();
        expect(screen.queryByText('URL is too long')).not.toBeInTheDocument();
        setURL(`https://outlook.live.com/${'a'.repeat(MAX_LENGTHS_API.CALENDAR_URL)}`);
        expect(screen.getByText('This link might be wrong')).toBeInTheDocument();
    });
});
